input.command:
cd /home/salboaie/work/sopworlds/soplang-nlu/eval-results/2026-11-28-vibe-batches/drawing && python3 - <<'EOF'
import csv,re
rows=list(csv.DictReader(open('objects-01-advanced.p01.csv')))
for r in rows:
    ids={}; refs=set()
    for line in r['sop'].splitlines():
        line=line.strip()
        if not line: continue
        m=re.match(r'@(\w+)\s+(\S+)(.*)$',line)
        ids[m.group(1)]=(m.group(2),m.group(3))
        for x in re.findall(r'\$(\w+)',m.group(3)): refs.add(x)
    cl=[k for k in ids if ids[k][0]=='syntax.clause' and k not in refs]
    if len(cl)>1:
        print(r['n'],'|',r['text'][:80])
        for k in cl: print('   ',k,ids[k][1])
EOF

